export const HTML_PAGE = `<!DOCTYPE html>
<html lang="uk">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>WebSales — Парсер продуктів</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      background: #1a1a2e;
      color: #e0e0e0;
      min-height: 100vh;
    }
    .header {
      background: linear-gradient(135deg, #16213e, #0f3460);
      padding: 16px 24px;
      display: flex;
      align-items: center;
      gap: 12px;
      flex-wrap: wrap;
      border-bottom: 2px solid #e94560;
      box-shadow: 0 2px 15px rgba(233,69,96,0.15);
    }
    .header h1 {
      font-size: 18px;
      color: #e94560;
      margin-right: 12px;
      white-space: nowrap;
    }
    select, input, button {
      padding: 8px 12px;
      border: 1px solid #333;
      border-radius: 6px;
      font-size: 14px;
      background: #16213e;
      color: #e0e0e0;
      outline: none;
      transition: border-color 0.2s;
    }
    select:focus, input:focus { border-color: #e94560; }
    select { min-width: 180px; max-width: 320px; }
    input { min-width: 160px; }
    button {
      background: #e94560;
      color: white;
      border: none;
      cursor: pointer;
      font-weight: 600;
      white-space: nowrap;
    }
    button:hover { background: #c73652; }
    button:disabled { background: #555; cursor: not-allowed; }
    .controls { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .search-group { display: flex; align-items: center; gap: 6px; margin-left: auto; }

    .table-wrap {
      overflow-x: auto;
      padding: 16px;
    }
    table {
      width: 100%;
      border-collapse: collapse;
      font-size: 13px;
    }
    thead th {
      background: #16213e;
      color: #e94560;
      padding: 10px 8px;
      text-align: left;
      position: sticky;
      top: 0;
      white-space: nowrap;
      border-bottom: 2px solid #e94560;
      cursor: pointer;
      user-select: none;
      transition: background 0.15s;
    }
    thead th:hover { background: #1a2a4e; }
    thead th .sort-arrow {
      display: inline-block;
      margin-left: 4px;
      font-size: 10px;
      opacity: 0.4;
    }
    thead th.sorted .sort-arrow { opacity: 1; }
    tbody tr { border-bottom: 1px solid #2a2a4a; }
    tbody tr:hover { background: rgba(233,69,96,0.07); }
    td { padding: 8px; vertical-align: middle; }
    .price { font-weight: 700; color: #4ecca3; white-space: nowrap; }
    .old-price { color: #888; text-decoration: line-through; white-space: nowrap; }
    .discount {
      font-weight: 700;
      white-space: nowrap;
    }
    .discount.has { color: #4ecca3; }
    .btn-link {
      display: inline-block;
      padding: 4px 10px;
      background: #0f3460;
      color: #4ecca3;
      text-decoration: none;
      border-radius: 4px;
      font-size: 12px;
      white-space: nowrap;
    }
    .btn-link:hover { background: #1a4a7a; }
    .status-bar {
      padding: 8px 24px;
      background: #16213e;
      color: #888;
      font-size: 13px;
      border-top: 1px solid #2a2a4a;
    }
    .loader {
      display: none;
      padding: 40px;
      text-align: center;
      color: #e94560;
      font-size: 16px;
    }
    .loader.active { display: block; }
    .store-tag {
      display: inline-block;
      padding: 2px 8px;
      border-radius: 10px;
      font-size: 11px;
      font-weight: 600;
      white-space: nowrap;
    }
    .store-tag.silpo { background: #2d6a4f; color: #b7e4c7; }
    .store-tag.novus { background: #1d3557; color: #a8dadc; }
  </style>
</head>
<body>
  <div class="header">
    <h1>🛒 WebSales</h1>
    <div class="controls">
      <select id="store">
        <option value="">-- Магазин --</option>
        <option value="silpo">Сільпо</option>
        <option value="novus">Новус</option>
      </select>
      <select id="category" disabled>
        <option value="">-- Категорія --</option>
      </select>
      <button id="btnFind" disabled>Знайти товари</button>
    </div>
    <div class="search-group">
      <input type="text" id="searchInput" placeholder="Пошук товару..." />
      <button id="btnSearch">Пошук</button>
    </div>
  </div>

  <div class="loader" id="loader">⏳ Завантаження...</div>

  <div class="table-wrap">
    <table>
      <thead>
        <tr>
          <th data-key="store">Магазин <span class="sort-arrow">▲▼</span></th>
          <th data-key="name">Назва продукту <span class="sort-arrow">▲▼</span></th>
          <th data-key="category">Категорія <span class="sort-arrow">▲▼</span></th>
          <th data-key="price">Поточна ціна <span class="sort-arrow">▲▼</span></th>
          <th data-key="oldPrice">Стара ціна <span class="sort-arrow">▲▼</span></th>
          <th data-key="discount">Знижка % <span class="sort-arrow">▲▼</span></th>
          <th>Посилання</th>
        </tr>
      </thead>
      <tbody id="tableBody"></tbody>
    </table>
  </div>

  <div class="status-bar" id="statusBar">Оберіть магазин та категорію.</div>

  <script>
    const storeSelect = document.getElementById('store');
    const catSelect = document.getElementById('category');
    const btnFind = document.getElementById('btnFind');
    const searchInput = document.getElementById('searchInput');
    const btnSearch = document.getElementById('btnSearch');
    const tableBody = document.getElementById('tableBody');
    const statusBar = document.getElementById('statusBar');
    const loader = document.getElementById('loader');

    let allProducts = [];
    let displayProducts = [];
    let currentSort = { key: null, dir: 1 }; // 1 = asc, -1 = desc

    // ——— Сортировка по столбцам ———
    document.querySelectorAll('thead th[data-key]').forEach(th => {
      th.addEventListener('click', () => {
        const key = th.dataset.key;
        if (currentSort.key === key) {
          currentSort.dir *= -1;
        } else {
          currentSort.key = key;
          currentSort.dir = key === 'discount' ? 1 : 1; // по-умолч asc
        }
        // Убираем класс sorted у всех
        document.querySelectorAll('thead th').forEach(t => t.classList.remove('sorted'));
        th.classList.add('sorted');
        th.querySelector('.sort-arrow').textContent = currentSort.dir === 1 ? '▲' : '▼';

        sortAndRender();
      });
    });

    function sortAndRender() {
      const key = currentSort.key;
      const dir = currentSort.dir;
      if (!key) { renderProducts(displayProducts); return; }

      displayProducts.sort((a, b) => {
        let va = a[key];
        let vb = b[key];
        // null / undefined в конец
        if (va == null && vb == null) return 0;
        if (va == null) return 1;
        if (vb == null) return -1;
        // числа
        if (typeof va === 'number' && typeof vb === 'number') {
          return (va - vb) * dir;
        }
        // строки
        return String(va).localeCompare(String(vb), 'uk') * dir;
      });
      renderProducts(displayProducts);
    }

    // ——— Загрузка категорий ———
    storeSelect.addEventListener('change', async () => {
      const store = storeSelect.value;
      catSelect.innerHTML = '<option value="">-- Категорія --</option>';
      catSelect.disabled = true;
      btnFind.disabled = true;
      allProducts = [];
      displayProducts = [];
      tableBody.innerHTML = '';
      statusBar.textContent = 'Оберіть магазин та категорію.';

      if (!store) return;

      loader.classList.add('active');
      statusBar.textContent = 'Завантаження категорій...';

      try {
        const resp = await fetch('/api/' + store + '/categories');
        const data = await resp.json();

        let categories = Array.isArray(data) ? data : [];
        categories.forEach(c => {
          if (c.count === 0) return;
          const opt = document.createElement('option');
          opt.value = c.id;
          opt.textContent = c.title + (c.count ? ' (' + c.count + ')' : '');
          catSelect.appendChild(opt);
        });

        catSelect.disabled = false;
        btnFind.disabled = false;
        statusBar.textContent = 'Категорії завантажені (' + categories.filter(c => c.count > 0).length + '). Оберіть категорію.';
      } catch (err) {
        statusBar.textContent = 'Помилка: ' + err.message;
      }
      loader.classList.remove('active');
    });

    // ——— Загрузка товарів ———
    btnFind.addEventListener('click', loadProducts);

    async function loadProducts() {
      const store = storeSelect.value;
      const category = catSelect.value;
      if (!store) return;

      loader.classList.add('active');
      btnFind.disabled = true;
      statusBar.textContent = 'Завантаження товарів...';
      tableBody.innerHTML = '';
      allProducts = [];
      displayProducts = [];

      try {
        let url = '/api/' + store + '/products?category=' + encodeURIComponent(category);
        const resp = await fetch(url);
        const data = await resp.json();

        if (data.error) {
          statusBar.textContent = 'Помилка: ' + data.error;
          loader.classList.remove('active');
          btnFind.disabled = false;
          return;
        }

        allProducts = data.products || [];
        displayProducts = [...allProducts];

        // По-умолч сортируем по скидке (самая большая скидка первая)
        currentSort = { key: 'discount', dir: 1 };
        document.querySelectorAll('thead th').forEach(t => t.classList.remove('sorted'));
        const discTh = document.querySelector('thead th[data-key="discount"]');
        if (discTh) { discTh.classList.add('sorted'); discTh.querySelector('.sort-arrow').textContent = '▲'; }

        sortAndRender();
        statusBar.textContent = 'Завантажено ' + allProducts.length + ' товарів' + (data.total ? ' з ' + data.total : '') + '.';
      } catch (err) {
        statusBar.textContent = 'Помилка: ' + err.message;
      }

      loader.classList.remove('active');
      btnFind.disabled = false;
    }

    // ——— Пошук ———
    btnSearch.addEventListener('click', doSearch);
    searchInput.addEventListener('keydown', e => { if (e.key === 'Enter') doSearch(); });

    function doSearch() {
      const q = searchInput.value.trim().toLowerCase();
      if (!q) {
        displayProducts = [...allProducts];
      } else {
        displayProducts = allProducts.filter(p =>
          p.name.toLowerCase().includes(q) ||
          p.category.toLowerCase().includes(q)
        );
      }
      sortAndRender();
      if (q) {
        statusBar.textContent = 'Знайдено ' + displayProducts.length + ' з ' + allProducts.length + ' товарів.';
      } else {
        statusBar.textContent = 'Завантажено ' + allProducts.length + ' товарів.';
      }
    }

    // ——— Рендер таблиці ———
    function renderProducts(products) {
      tableBody.innerHTML = '';
      for (const p of products) {
        const tr = document.createElement('tr');
        const storeClass = p.store === 'Сільпо' ? 'silpo' : 'novus';

        tr.innerHTML =
          '<td><span class="store-tag ' + storeClass + '">' + esc(p.store) + '</span></td>' +
          '<td>' + esc(p.name) + '</td>' +
          '<td>' + esc(p.category) + '</td>' +
          '<td class="price">' + formatPrice(p.price) + '</td>' +
          '<td class="old-price">' + (p.oldPrice ? formatPrice(p.oldPrice) : '—') + '</td>' +
          '<td class="discount' + (p.discount != null ? ' has' : '') + '">' + (p.discount != null ? p.discount + '%' : '—') + '</td>' +
          '<td><a class="btn-link" href="' + esc(p.url) + '" target="_blank" rel="noopener">Відкрити</a></td>';
        tableBody.appendChild(tr);
      }
    }

    function formatPrice(v) {
      if (v == null) return '—';
      return parseFloat(v).toFixed(2) + ' ₴';
    }

    function esc(str) {
      if (!str) return '';
      return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    }
  </script>
</body>
</html>`;
